363: template <bool isAIVOnly = true>
364: __aicore__ inline void SyncAllImpl()
365: {
366: #if defined(__ASCENDC_SUPERKERNEL_AUTO_SYNC_ALL__)
367:     if (g_superKernelAutoSyncAllEnable) {
368:         if (GetBlockIdxImpl() == 0) {
369:             g_superKernelAutoSyncAllSyncIdx += 1;
370:             // |    32bits  |   16bits  |   8bits   |   8bits   |
371:             // |  sync idx  | sync type |   is end  | is valid  |
372:             *reinterpret_cast<__gm__ uint64_t*>(g_superKernelAutoSyncAllConfigGmAddr) =
373:                 (static_cast<uint64_t>(g_superKernelAutoSyncAllSyncIdx)
374:                  << SK_AUTO_SYNC_ALL_SYNC_IDX_CONFIG_BIT_OFFSET) |
375:                 (static_cast<uint64_t>(isAIVOnly) << SK_AUTO_SYNC_ALL_SYNC_TYPE_CONFIG_BIT_OFFSET) |
376:                 static_cast<uint64_t>(SK_AUTO_SYNC_ALL_VALID_MAGIC_NUM);
377:             dcci(
378:                 reinterpret_cast<__gm__ uint64_t*>(g_superKernelAutoSyncAllConfigGmAddr),
379:                 cache_line_t::SINGLE_CACHE_LINE, dcci_dst_t::CACHELINE_OUT);
380:         }
381:     }
382: #endif
383: 
384:     PipeBarrier<PIPE_ALL>();
385:     if constexpr (isAIVOnly) {
386:         ffts_cross_core_sync(PIPE_MTE3, GetffstMsg(0x0, SYNC_AIV_ONLY_ALL));
387:         wait_flag_dev(SYNC_AIV_ONLY_ALL);
388:         return;
389:     }
390:     // trans software sync to hardware sync
391:     if ASCEND_IS_AIC {
392:         wait_flag_dev(SYNC_AIV_FLAG);
393:         ffts_cross_core_sync(PIPE_FIX, GetffstMsg(0x0, SYNC_AIC_FLAG));
394:         wait_flag_dev(SYNC_AIC_FLAG);
395:         ffts_cross_core_sync(PIPE_MTE3, GetffstMsg(0x02, SYNC_AIC_AIV_FLAG));
396:         return;
397:     }
398:     if ASCEND_IS_AIV {
399:         ffts_cross_core_sync(PIPE_MTE3, GetffstMsg(0x02, SYNC_AIV_FLAG));
400:         wait_flag_dev(SYNC_AIC_AIV_FLAG);
401:         return;
402:     }
403: }

